from kohakutpu.language.examples.dsl.vector.softmax import softmax


@kt.kernel
def two(x=kt.In(4, 32), y=kt.Out(4, 32), *, a=kt.auto(1, 2), b=kt.auto(10, 20)):
    kt.require(a + b in (12, 21), "no")
    for c in kt.par(1, on=kt.vc):
        kt.store(y[0:4, :], kt.load(x[0:4, :]))


def facts():
    g = {"x": TY.TensorSpec.make((4, 32))}
    sm = softmax.trace({"x": TY.TensorSpec.make((16, 128))}, machine=MACHINE)
    first = two.trace(g, machine=MACHINE)
    no21 = lambda t: kt.require(t.consts["a"] + t.consts["b"] != 21, "21")
    checked = two.trace(g, machine=MACHINE, check=no21)
    return {
        "softmax_rows": sm.consts["rows"],
        "first": [first.consts["a"], first.consts["b"]],
        "checked": [checked.consts["a"], checked.consts["b"]],
    }
